          '{{$json.member_name}}': String(recipient && recipient.target_member_names || ''),
          '{{$json.member_names}}': String(recipient && recipient.target_member_names || ''),
          '{{$json.target_member_name}}': String(recipient && recipient.target_member_names || ''),
          '{{$json.target_member_names}}': String(recipient && recipient.target_member_names || ''),
          '{{$json.target_first_names}}': String(recipient && recipient.target_first_names || ''),
          '{{$json.target_last_names}}': String(recipient && recipient.target_last_names || ''),
          '{{$json.member_first_names}}': String(recipient && recipient.target_first_names || ''),
          '{{$json.member_last_names}}': String(recipient && recipient.target_last_names || ''),
          '{{$json.target_member_count}}': String(recipient && recipient.target_member_count || 0),
          '{{$json.member_count}}': String(recipient && recipient.target_member_count || 0),
          '{{$json.recipient_name}}': String(recipient && recipient.recipient_name || ''),
          '{{$json.recipient_first_name}}': String(recipient && recipient.recipient_first_name || ''),
          '{{$json.recipient_last_name}}': String(recipient && recipient.recipient_last_name || ''),
          '{{list_name}}': String(item.list_label || ''),
          '{{list_label}}': String(item.list_label || ''),
          '{{list_key}}': String(item.list_key || ''),
          '{{recipient_count}}': String(item.included_recipient_count ?? item.recipient_count ?? 0),
          '{{current_season}}': String(item.current_season || ''),
          '{{previous_season}}': String(item.previous_season || ''),
          '{{first_name}}': String(recipient && recipient.target_first_names || ''),
          '{{last_name}}': String(recipient && recipient.target_last_names || ''),
          '{{member_name}}': String(recipient && recipient.target_member_names || ''),
          '{{member_names}}': String(recipient && recipient.target_member_names || ''),
          '{{target_member_name}}': String(recipient && recipient.target_member_names || ''),
          '{{target_member_names}}': String(recipient && recipient.target_member_names || ''),
          '{{target_first_names}}': String(recipient && recipient.target_first_names || ''),
          '{{target_last_names}}': String(recipient && recipient.target_last_names || ''),
          '{{member_first_names}}': String(recipient && recipient.target_first_names || ''),
          '{{member_last_names}}': String(recipient && recipient.target_last_names || ''),
          '{{target_member_count}}': String(recipient && recipient.target_member_count || 0),
          '{{member_count}}': String(recipient && recipient.target_member_count || 0),
          '{{recipient_name}}': String(recipient && recipient.recipient_name || ''),
          '{{recipient_first_name}}': String(recipient && recipient.recipient_first_name || ''),
          '{{recipient_last_name}}': String(recipient && recipient.recipient_last_name || ''),
        };
        Object.keys(tokenMap).forEach(function(token) { rendered = rendered.split(token).join(tokenMap[token]); });
        return rendered.trim();
      };
      var updateRecipientSelectionState = function() {
        var checkboxes = Array.prototype.slice.call(document.querySelectorAll('.recipient-include-checkbox'));
        var allKeys = {};
        var includedKeys = {};
        checkboxes.forEach(function(checkbox) {
          var key = String(checkbox.getAttribute('data-recipient-key') || '').toLowerCase();
          if (!key) return;
          allKeys[key] = true;
          if (checkbox.checked) includedKeys[key] = true;
        });
        document.querySelectorAll('[data-recipient-card]').forEach(function(card) {
          var checkbox = card.querySelector('.recipient-include-checkbox');
          var included = checkbox ? checkbox.checked : false;
          card.classList.toggle('is-excluded', !included);
          var status = card.querySelector('.recipient-status');
          if (status) {
            status.textContent = included ? 'Included' : 'Excluded';
            status.classList.toggle('is-excluded', !included);
          }
        });
        var includedTotal = Object.keys(includedKeys).length;
        var total = Object.keys(allKeys).length;
        if (selectionSummary) selectionSummary.textContent = includedTotal + ' included / ' + total + ' total';
        if (includedCountLabel) includedCountLabel.textContent = String(includedTotal);
        if (excludedCountLabel) excludedCountLabel.textContent = String(Math.max(total - includedTotal, 0));
      };
      window.__memberListToggleRecipient = function(key, checked) {
        document.querySelectorAll('.recipient-include-checkbox').forEach(function(checkbox) {
          if (String(checkbox.getAttribute('data-recipient-key') || '').toLowerCase() === String(key || '').toLowerCase()) {
            if (checkbox.disabled) return;
            checkbox.checked = checked;
          }
        });
        updateRecipientSelectionState();
      };
      window.__memberListSetAll = function(checked) {
        document.querySelectorAll('.recipient-include-checkbox').forEach(function(checkbox) { if (!checkbox.disabled) checkbox.checked = checked; });
        updateRecipientSelectionState();
      };
      var setSelectedRecipientIndex = function(index) {
        var recipients = Array.isArray(item.recipients) ? item.recipients : [];
