        if (previewTargetMembersLabel) previewTargetMembersLabel.textContent = recipient ? (recipient.target_member_names || '') : '';
        if (subjectPreview && subjectInput) subjectPreview.textContent = replaceTokens(String(subjectInput.value || ''), recipient);
