            <div><span class='meta-label'>Recipient List</span><strong>${escapeHtml(item.list_label)}</strong></div>
            <div><span class='meta-label'>Resolved Recipients</span><strong>${escapeHtml(String(item.recipient_count || 0))}</strong></div>
            <div><span class='meta-label'>Included Recipients</span><strong id='included-recipient-count'>${escapeHtml(String(includedCount || 0))}</strong></div>
            <div><span class='meta-label'>Excluded Recipients</span><strong id='excluded-recipient-count'>${escapeHtml(String(excludedCount || 0))}</strong></div>
            <div><span class='meta-label'>Template</span><strong>${escapeHtml(item.template_name || item.template_key)}</strong></div>
            <div><span class='meta-label'>Visible Club Address</span><strong>${escapeHtml(item.reply_to || '')}</strong></div>
            <div><span class='meta-label'>Test Recipient</span><strong>${escapeHtml(item.test_recipient || '')}</strong></div>
            <div><span class='meta-label'>Send Delay</span><strong>${escapeHtml(String(item.send_delay_seconds ?? 5))} seconds between production messages</strong></div>
            <div><span class='meta-label'>Preview Recipient</span><strong id='preview-recipient-label'>${escapeHtml(item.preview_recipient_name || '')}</strong></div>
            <div><span class='meta-label'>Target Members</span><strong id='preview-target-members-label'>${escapeHtml(item.preview_target_member_names || '')}</strong></div>
            <div><span class='meta-label'>Sample Subject</span><strong id='rendered-subject-preview'>${escapeHtml(item.preview_subject || item.rendered_subject || '')}</strong></div>
          </div>
          <p style='margin:14px 0 0;color:var(--muted);line-height:1.6;'>${escapeHtml(item.list_description || '')}</p>
        </section>
        <section class='panel'>
          <h2 style='margin:0 0 12px;font-size:19px;'>Recipient Preview</h2>
          ${recipientSelectorHtml}
          ${sampleHtml ? `<ul class='sample-list'>${sampleHtml}</ul>` : emptySampleHtml}
          ${recipientListDetailsHtml}
        </section>
        <section class='panel'>
          <h2 style='margin:0 0 12px;font-size:19px;'>Signature Preview</h2>
          <div id='signature-preview-shell'>${signatureHtml}</div>
        </section>
        <section class='panel'>
          <h2 style='margin:0 0 12px;font-size:19px;'>Rendered Preview For Selected Recipient</h2>
          ${previewHtml}
        </section>
      </aside>
    </section>
  </div>
  <script>
    (function() {
      var item = ${toScript(item)};
      var emailType = String(item.email_type || 'text');
      var form = document.getElementById('compose-form');
      var host = document.getElementById('message-editor-host');
      var input = document.getElementById('message-editor-input');
      var output = document.getElementById('rendered-message-output');
      var preview = document.getElementById('rendered-preview');
      var signaturePreview = document.getElementById('signature-preview');
      var subjectInput = form ? form.querySelector('input[name="rendered_subject"]') : null;
      var subjectPreview = document.getElementById('rendered-subject-preview');
      var previewRecipientLabel = document.getElementById('preview-recipient-label');
      var previewTargetMembersLabel = document.getElementById('preview-target-members-label');
      var selectionSummary = document.getElementById('recipient-selection-summary');
      var includedCountLabel = document.getElementById('included-recipient-count');
      var excludedCountLabel = document.getElementById('excluded-recipient-count');
      var selectedRecipientIndex = ${initialPreviewIndex};
      var initialBody = String(item.rendered_body || '');
      var signature = String(item.rendered_signature || '');
      var consentFooter = String(emailType === 'html' ? (item.consent_footer_html || '') : (item.consent_footer_text || ''));
      var normalizeHtml = function(value) { return String(value || '').replace(/<!doctype[^>]*>/ig, '').replace(/<\\/?(?:html|body)[^>]*>/ig, '').trim(); };
      var replaceTokens = function(value, recipient) {
        var rendered = String(value || '');
        var tokenMap = {
          '{{$json.list_name}}': String(item.list_label || ''),
          '{{$json.list_label}}': String(item.list_label || ''),
          '{{$json.list_key}}': String(item.list_key || ''),
          '{{$json.recipient_count}}': String(item.included_recipient_count ?? item.recipient_count ?? 0),
          '{{$json.current_season}}': String(item.current_season || ''),
          '{{$json.previous_season}}': String(item.previous_season || ''),
          '{{$json.first_name}}': String(recipient && recipient.target_first_names || ''),
          '{{$json.last_name}}': String(recipient && recipient.target_last_names || ''),
          '{{$json.member_name}}': String(recipient && recipient.target_member_names || ''),
          '{{$json.member_names}}': String(recipient && recipient.target_member_names || ''),
          '{{$json.target_member_name}}': String(recipient && recipient.target_member_names || ''),
          '{{$json.target_member_names}}': String(recipient && recipient.target_member_names || ''),
          '{{$json.target_first_names}}': String(recipient && recipient.target_first_names || ''),
          '{{$json.target_last_names}}': String(recipient && recipient.target_last_names || ''),
          '{{$json.member_first_names}}': String(recipient && recipient.target_first_names || ''),
          '{{$json.member_last_names}}': String(recipient && recipient.target_last_names || ''),
          '{{$json.target_member_count}}': String(recipient && recipient.target_member_count || 0),
          '{{$json.member_count}}': String(recipient && recipient.target_member_count || 0),
          '{{$json.recipient_name}}': String(recipient && recipient.recipient_name || ''),
          '{{$json.recipient_first_name}}': String(recipient && recipient.recipient_first_name || ''),
          '{{$json.recipient_last_name}}': String(recipient && recipient.recipient_last_name || ''),
          '{{list_name}}': String(item.list_label || ''),
          '{{list_label}}': String(item.list_label || ''),
          '{{list_key}}': String(item.list_key || ''),
          '{{recipient_count}}': String(item.included_recipient_count ?? item.recipient_count ?? 0),
          '{{current_season}}': String(item.current_season || ''),
          '{{previous_season}}': String(item.previous_season || ''),
          '{{first_name}}': String(recipient && recipient.target_first_names || ''),
          '{{last_name}}': String(recipient && recipient.target_last_names || ''),
          '{{member_name}}': String(recipient && recipient.target_member_names || ''),
          '{{member_names}}': String(recipient && recipient.target_member_names || ''),
          '{{target_member_name}}': String(recipient && recipient.target_member_names || ''),
          '{{target_member_names}}': String(recipient && recipient.target_member_names || ''),
          '{{target_first_names}}': String(recipient && recipient.target_first_names || ''),
          '{{target_last_names}}': String(recipient && recipient.target_last_names || ''),
          '{{member_first_names}}': String(recipient && recipient.target_first_names || ''),
          '{{member_last_names}}': String(recipient && recipient.target_last_names || ''),
          '{{target_member_count}}': String(recipient && recipient.target_member_count || 0),
          '{{member_count}}': String(recipient && recipient.target_member_count || 0),
          '{{recipient_name}}': String(recipient && recipient.recipient_name || ''),
          '{{recipient_first_name}}': String(recipient && recipient.recipient_first_name || ''),
          '{{recipient_last_name}}': String(recipient && recipient.recipient_last_name || ''),
        };
        Object.keys(tokenMap).forEach(function(token) { rendered = rendered.split(token).join(tokenMap[token]); });
        return rendered.trim();
      };
      var updateRecipientSelectionState = function() {
        var checkboxes = Array.prototype.slice.call(document.querySelectorAll('.recipient-include-checkbox'));
        var allKeys = {};
        var includedKeys = {};
        checkboxes.forEach(function(checkbox) {
          var key = String(checkbox.getAttribute('data-recipient-key') || '').toLowerCase();
          if (!key) return;
          allKeys[key] = true;
          if (checkbox.checked) includedKeys[key] = true;
        });
        document.querySelectorAll('[data-recipient-card]').forEach(function(card) {
          var checkbox = card.querySelector('.recipient-include-checkbox');
          var included = checkbox ? checkbox.checked : false;
          card.classList.toggle('is-excluded', !included);
          var status = card.querySelector('.recipient-status');
          if (status) {
            status.textContent = included ? 'Included' : 'Excluded';
            status.classList.toggle('is-excluded', !included);
          }
        });
        var includedTotal = Object.keys(includedKeys).length;
        var total = Object.keys(allKeys).length;
        if (selectionSummary) selectionSummary.textContent = includedTotal + ' included / ' + total + ' total';
        if (includedCountLabel) includedCountLabel.textContent = String(includedTotal);
        if (excludedCountLabel) excludedCountLabel.textContent = String(Math.max(total - includedTotal, 0));
      };
      window.__memberListToggleRecipient = function(key, checked) {
        document.querySelectorAll('.recipient-include-checkbox').forEach(function(checkbox) {
          if (String(checkbox.getAttribute('data-recipient-key') || '').toLowerCase() === String(key || '').toLowerCase()) {
            if (checkbox.disabled) return;
            checkbox.checked = checked;
          }
        });
        updateRecipientSelectionState();
      };
      window.__memberListSetAll = function(checked) {
        document.querySelectorAll('.recipient-include-checkbox').forEach(function(checkbox) { if (!checkbox.disabled) checkbox.checked = checked; });
        updateRecipientSelectionState();
      };
      var setSelectedRecipientIndex = function(index) {
        var recipients = Array.isArray(item.recipients) ? item.recipients : [];
        var maxIndex = Math.max(recipients.length - 1, 0);
        var nextIndex = Number.isFinite(index) ? Math.max(0, Math.min(maxIndex, index)) : 0;
        selectedRecipientIndex = nextIndex;
        document.querySelectorAll('[data-preview-index]').forEach(function(button) {
          var buttonIndex = Number(button.getAttribute('data-preview-index') || 0);
          var isSelected = buttonIndex === selectedRecipientIndex;
          button.classList.toggle('is-selected', isSelected);
          button.setAttribute('aria-pressed', isSelected ? 'true' : 'false');
        });
      };
      var getSelectedRecipient = function() {
        var recipients = Array.isArray(item.recipients) ? item.recipients : [];
        return recipients[selectedRecipientIndex] || recipients[0] || null;
      };
      window.__memberListSelectRecipient = function(index) {
        setSelectedRecipientIndex(Number(index || 0));
        syncPreview();
      };
      var getValue = function() {
        if (emailType === 'html') {
          var editor = window.tinymce ? window.tinymce.get('member-list-mailout-editor') : null;
          if (editor) return editor.getContent({ format: 'html' });
          return host ? host.innerHTML : '';
        }
        return input ? String(input.value || '') : '';
      };
      var syncPreview = function() {
        var message = getValue();
        var recipient = getSelectedRecipient();
        var renderedSignature = replaceTokens(String(signature || ''), recipient);
        if (previewRecipientLabel) previewRecipientLabel.textContent = recipient ? (recipient.recipient_name || recipient.recipient_email || '') : '';
        if (previewTargetMembersLabel) previewTargetMembersLabel.textContent = recipient ? (recipient.target_member_names || '') : '';
        if (subjectPreview && subjectInput) subjectPreview.textContent = replaceTokens(String(subjectInput.value || ''), recipient);
        if (signaturePreview) {
          if (emailType === 'html') signaturePreview.innerHTML = normalizeHtml(renderedSignature);
          else signaturePreview.textContent = renderedSignature;
        }
        if (!preview) return;
        if (emailType === 'html') {
          preview.innerHTML = normalizeHtml(replaceTokens(String(message || '') + String(signature || '') + consentFooter, recipient));
        } else {
          preview.textContent = replaceTokens([String(message || '').trim(), String(signature || '').trim(), consentFooter].filter(Boolean).join('\\n\\n'), recipient);
        }
      };
      var syncSubmit = function() {
        var message = getValue();
        output.value = emailType === 'html' ? normalizeHtml(message) : String(message || '').trim();
      };
      if (emailType === 'html' && host) {
        host.innerHTML = normalizeHtml(initialBody);
        ['input', 'keyup', 'paste', 'blur'].forEach(function(eventName) {
          host.addEventListener(eventName, syncPreview);
        });
      } else if (input) {
        input.value = initialBody;
        ['input', 'keyup', 'change', 'paste', 'blur'].forEach(function(eventName) {
          input.addEventListener(eventName, syncPreview);
        });
      }
      if (subjectInput) { ['input', 'keyup', 'change', 'paste', 'blur'].forEach(function(eventName) { subjectInput.addEventListener(eventName, syncPreview); }); }
      setSelectedRecipientIndex(${initialPreviewIndex});
      updateRecipientSelectionState();
      syncPreview();
      form.addEventListener('submit', function() { syncSubmit(); updateRecipientSelectionState(); });
    })();
  </script>
</body>
</html>`;
return [{ json: { html } }];
